<section class="page-head"><div class="eyebrow">Journal</div><h1>Blog</h1></section><section class="section"><div class="posts"><?php foreach ($posts as $post): ?><article class="post-card"><div class="date"><?= e(substr((string)$post['published_at'],0,10)) ?></div><h2><a href="/blog/<?= e($post['slug']) ?>"><?= e($post['title']) ?></a></h2><p><?= e($post['excerpt'] ?: '') ?></p></article><?php endforeach; ?><?php if (!$posts): ?><div class="empty">No published posts yet.</div><?php endif; ?></div></section>
